const responseText = $json.text || $json.content || ($json.message && $json.message.content) || $json.output || JSON.stringify($json);
let cleaned = String(responseText).trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { category: 'normal', action: 'file', summary: 'Could not parse classifier output', suggested_reply: '', confirmation_required: false, has_calendar_action: false, event_title: '', event_start_iso: '', event_end_iso: '' };
}

const validCategories = ['urgent', 'normal', 'newsletter', 'spam'];
const validActions = ['reply', 'draft', 'file', 'ignore'];

const category = validCategories.includes(parsed.category) ? parsed.category : 'normal';
const action = validActions.includes(parsed.action) ? parsed.action : 'file';
const confirmation_required = (category === 'urgent' || category === 'normal');
const requires_reply = (action === 'reply' || action === 'draft');
const has_calendar_action = (parsed.has_calendar_action === true) && Boolean(parsed.event_start_iso) && Boolean(parsed.event_end_iso);

const originalEmail = $('Gmail Trigger').first().json || {};
function headerVal(headers, name) {
  if (!Array.isArray(headers)) return '';
  const h = headers.find(x => (x.name || '').toLowerCase() === name.toLowerCase());
  return h ? (h.value || '') : '';
}
const headersArr = (originalEmail.payload && originalEmail.payload.headers) || originalEmail.headers || [];
const from_email = originalEmail.from || originalEmail.From || (originalEmail.headers && originalEmail.headers.from) || headerVal(headersArr, 'From') || '';
const subject = originalEmail.subject || originalEmail.Subject || (originalEmail.headers && originalEmail.headers.subject) || headerVal(headersArr, 'Subject') || '';
const threadId = originalEmail.threadId || '';
const messageId = originalEmail.id || originalEmail.messageId || '';

return {
  json: {
    category, action, confirmation_required, requires_reply,
    summary: parsed.summary || '',
    suggested_reply: parsed.suggested_reply || '',
    has_calendar_action,
    event_title: parsed.event_title || '',
    event_start_iso: parsed.event_start_iso || '',
    event_end_iso: parsed.event_end_iso || '',
    from_email, subject, threadId, messageId
  }
};

const parsed = $('Parse Classifier Output').first().json;

let slot_free = false;
let conflict_summary = '';

if (parsed.has_calendar_action) {
  // Came through Check Availability; $json includes a `busy` array or `available` field.
  const availData = $json;
  let busy = [];
  if (Array.isArray(availData.busy)) busy = availData.busy;
  else if (Array.isArray(availData.primary && availData.primary.busy)) busy = availData.primary.busy;
  else if (availData.available === true) busy = [];
  else if (availData.available === false) busy = [{ start: parsed.event_start_iso, end: parsed.event_end_iso, summary: 'existing event' }];

  const startMs = Date.parse(parsed.event_start_iso);
  const endMs = Date.parse(parsed.event_end_iso);
  if (isNaN(startMs) || isNaN(endMs)) {
    slot_free = false;
    conflict_summary = 'unparseable event time';
  } else {
    const conflict = busy.find(b => {
      const bs = Date.parse(b.start);
      const be = Date.parse(b.end);
      return !isNaN(bs) && !isNaN(be) && bs < endMs && be > startMs;
    });
    slot_free = !conflict;
    if (conflict) {
      conflict_summary = `${conflict.summary || 'existing event'} (${conflict.start} → ${conflict.end})`;
    }
  }
}

const replyPreview = (parsed.suggested_reply || '').substring(0, 500);
let cardText = `📧 *Draft Ready For Approval*\n\n`;
cardText += `*From:* ${parsed.from_email}\n`;
cardText += `*Subject:* ${parsed.subject}\n`;
cardText += `*Category:* ${parsed.category}\n\n`;
cardText += `*Proposed reply:*\n${replyPreview}\n\n`;

if (parsed.has_calendar_action) {
  cardText += `📅 *Will also create event:*\n${parsed.event_title}\n${parsed.event_start_iso} → ${parsed.event_end_iso}\n\n`;
  if (slot_free) {
    cardText += `✅ Slot is free. Approve → send reply + create event.\n`;
  } else {
    cardText += `⚠️ *Conflict:* ${conflict_summary}\nApprove → send reply ONLY; event will NOT be created.\n`;
  }
} else {
  cardText += `Approve → send the reply.\n`;
}
cardText += `\nReject → keep draft in Gmail (not sent). 24h timeout.`;

return {
  json: {
    ...parsed,
    slot_free,
    conflict_summary,
    cardText
  }
};

const parsed = $('Parse Classifier Output').first().json;
const card = $('Build Approval Card').first().json;
const eventCreated = parsed.has_calendar_action && card.slot_free;

return {
  json: {
    timestamp: new Date().toISOString(),
    action_type: 'proactive_approved',
    from_email: parsed.from_email || '',
    subject: parsed.subject || '',
    category: parsed.category || '',
    action: parsed.action || '',
    confirmation_required: parsed.confirmation_required ? 'true' : 'false',
    draft_created: 'false',
    email_sent: 'true',
    calendar_event_created: eventCreated ? 'true' : 'false',
    user_confirmed: 'yes'
  }
};

