const parsed = $('Parse Classifier Output').first().json;
const card = $('Build Approval Card').first().json;

function toGcalDates(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  return d.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
}

const startGcal = toGcalDates(parsed.event_start_iso);
const endGcal = toGcalDates(parsed.event_end_iso);
const title = encodeURIComponent(parsed.event_title || 'Event from email');
const details = encodeURIComponent(`Proposed via email from ${parsed.from_email}. Conflict detected with: ${card.conflict_summary || 'existing event'}.`);

const calendarUrl = (startGcal && endGcal)
  ? `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${title}&dates=${startGcal}/${endGcal}&details=${details}`
  : 'https://calendar.google.com/calendar/r';

const conflictText = `⚠️ *Calendar conflict — nothing was sent or created*

*From:* ${parsed.from_email}
*Subject:* ${parsed.subject}

*Proposed event:* ${parsed.event_title}
*When:* ${parsed.event_start_iso} → ${parsed.event_end_iso}

*Conflict:* ${card.conflict_summary || 'existing event in this slot'}

The email reply was saved to *Drafts* (NOT sent). You decide what to do:
👉 [Open calendar to resolve manually](${calendarUrl})

Once the calendar is sorted, send the email manually from Drafts.`;

return {
  json: {
    ...parsed,
    ...card,
    calendarUrl,
    conflictText
  }
};

const parsed = $('Parse Classifier Output').first().json;

return {
  json: {
    timestamp: new Date().toISOString(),
    action_type: 'proactive_conflict',
    from_email: parsed.from_email || '',
    subject: parsed.subject || '',
    category: parsed.category || '',
    action: parsed.action || '',
    confirmation_required: parsed.confirmation_required ? 'true' : 'false',
    draft_created: 'true',
    email_sent: 'false',
    calendar_event_created: 'false',
    user_confirmed: 'yes_but_conflict'
  }
};
